// Query TypeMap
import "@sanity/client";
declare module "@sanity/client" {
  interface SanityQueries {
    '\n  *[_type == "siteSettings"][0]{\n    title,\n    description,\n    brandName,\n    logo,\n    favicon,\n    tagline,\n    seoImage,\n    primaryPhone,\n    whatsappNumber,\n    primaryEmail,\n    businessAddress,\n    businessHours,\n    instagram,\n    facebook,\n    linkedin,\n    twitter,\n    youtube,\n    calcomUrl,\n    defaultWhatsappMessage,\n    copyrightText,\n    footerDescription,\n    supportEmail,\n    supportPhone,\n    expectedResponseTime\n  }\n': SettingsQueryResult;
    '\n  *[_type == "homepage"][0]{\n    title,\n    seo,\n    sections[]{\n      ...,\n      _type == "conditionsTreatedSection" => {\n        "conditions": conditions[]->{\n          _id,\n          title,\n          slug,\n          icon,\n          shortDescription\n        }\n      },\n      _type == "servicesPreviewSection" => {\n        "services": services[]->{\n          _id,\n          title,\n          slug,\n          image,\n          "shortDescription": description[0].children[0].text\n        }\n      },\n      _type == "testimonialsSection" => {\n        "testimonials": testimonials[]->{\n          _id,\n          clientName,\n          isAnonymous,\n          quote,\n          mediaType,\n          mediaFile,\n          conditionCategory->{title}\n        }\n      },\n      _type == "faqSection" => {\n        "faqs": faqs[]->{\n          _id,\n          question,\n          answer\n        }\n      },\n      _type == "blogPreviewSection" => {\n        "posts": *[_type == "post"] | order(publishedAt desc)[0...3]{\n          _id,\n          title,\n          slug,\n          mainImage,\n          publishedAt,\n          "excerpt": body[0].children[0].text,\n          author->{name},\n          categories[]->{title}\n        }\n      },\n      _type == "successStoriesSection" => {\n        "featuredStories": coalesce(\n          featuredStories[]->{\n            _id,\n            title,\n            slug,\n            clientName,\n            isAnonymous,\n            age,\n            gender,\n            areaOfConcern,\n            duration,\n            progressOutcome,\n            featuredImage\n          },\n          *[_type == "successStory" && featured == true] | order(publishedDate desc)[0...3]{\n            _id,\n            title,\n            slug,\n            clientName,\n            isAnonymous,\n            age,\n            gender,\n            areaOfConcern,\n            duration,\n            progressOutcome,\n            featuredImage\n          }\n        )\n      }\n    }\n  }\n': HomepageQueryResult;
    '\n  *[_type == "service"] | order(title asc){\n    _id,\n    title,\n    slug,\n    image,\n    "shortDescription": description[0].children[0].text\n  }\n': AllServicesQueryResult;
    '\n  *[_type == "service" && slug.current == $slug][0]{\n    _id,\n    title,\n    slug,\n    seo,\n    description,\n    whoItsFor,\n    conditionsCovered[]->{\n      _id,\n      title,\n      slug,\n      shortDescription,\n      icon\n    },\n    whatClientsReceive,\n    faqs[]->{\n      _id,\n      question,\n      answer\n    },\n    cta,\n    image\n  }\n': ServiceBySlugQueryResult;
    '\n  *[_type == "testimonial" && approvalStatus == "Approved"] | order(_createdAt desc){\n    _id,\n    clientName,\n    isAnonymous,\n    quote,\n    mediaType,\n    mediaFile,\n    conditionCategory->{title}\n  }\n': ApprovedTestimonialsQueryResult;
    '\n  *[_type == "post"] | order(publishedAt desc){\n    _id,\n    title,\n    slug,\n    mainImage,\n    publishedAt,\n    "excerpt": body[0].children[0].text,\n    author->{name, image},\n    categories[]->{title}\n  }\n': AllPostsQueryResult;
    '\n  *[_type == "post" && slug.current == $slug][0]{\n    _id,\n    title,\n    slug,\n    seo,\n    mainImage,\n    publishedAt,\n    body,\n    author->{name, image, bio},\n    categories[]->{title}\n  }\n': PostBySlugQueryResult;
    '\n  *[_type == "successStory"] | order(publishedDate desc){\n    _id,\n    title,\n    slug,\n    clientName,\n    isAnonymous,\n    age,\n    gender,\n    areaOfConcern,\n    duration,\n    progressOutcome,\n    featuredImage\n  }\n': AllSuccessStoriesQueryResult;
    '\n  *[_type == "successStory" && slug.current == $slug][0]{\n    _id,\n    title,\n    slug,\n    seo,\n    clientName,\n    isAnonymous,\n    age,\n    gender,\n    areaOfConcern,\n    duration,\n    progressOutcome,\n    shortSummary,\n    fullStory,\n    featuredImage,\n    beforeImage,\n    afterImage,\n    publishedDate\n  }\n': SuccessStoryBySlugQueryResult;
    '\n  *[_type == "navigation"][0]{\n    headerCtaText,\n    headerCtaLink,\n    headerNav[]{\n      label, href, openInNewTab, enabled, displayOrder, children[]{ label, href, openInNewTab, enabled }\n    },\n    footerQuickLinks[]{\n      label, href, openInNewTab, enabled, displayOrder, children[]{ label, href, openInNewTab, enabled }\n    },\n    footerResources[]{\n      label, href, openInNewTab, enabled, displayOrder, children[]{ label, href, openInNewTab, enabled }\n    },\n    footerContactSupport[]{\n      label, href, openInNewTab, enabled, displayOrder, children[]{ label, href, openInNewTab, enabled }\n    }\n  }\n': NavigationQueryResult;
    '\n  *[_type == "contactPage"][0]{\n    heroHeading,\n    heroSubtitle,\n    formHeading,\n    formDescription,\n    submitButtonText,\n    successMessage,\n    errorMessage,\n    socialHighlightText\n  }\n': ContactPageQueryResult;
    '\n  *[_type == "supportPage"][0]{\n    heroHeading,\n    heroDescription,\n    formHeading,\n    formDescription,\n    submitButtonText,\n    successMessage,\n    errorMessage,\n    helpSectionHeading1,\n    helpSectionHeading2\n  }\n': SupportPageQueryResult;
    '\n  *[_type == "bookConsultationPage"][0]{\n    heroHeading,\n    heroSubtitle,\n    unavailableMessage,\n    chatHeading,\n    chatDescription,\n    chatButtonText\n  }\n': BookConsultationPageQueryResult;
    '\n  *[_type == "successStoriesPage"][0]{\n    heroHeading,\n    heroSubtitle,\n    emptyStateHeading,\n    emptyStateDescription,\n    emptyStateButtonText\n  }\n': SuccessStoriesPageQueryResult;
    '\n  *[_type == "servicesPage"][0]{\n    seo,\n    hero,\n    cta\n  }\n': ServicesPageQueryResult;
    '\n  *[_type == "conditionsPage"][0]{\n    seo,\n    hero,\n    faq{\n      ...,\n      "faqs": faqs[]->{\n        _id,\n        question,\n        answer\n      }\n    },\n    cta\n  }\n': ConditionsPageQueryResult;
    '\n  *[_type == "condition"] | order(title asc){\n    _id,\n    title,\n    slug,\n    icon,\n    shortDescription\n  }\n': AllConditionsQueryResult;
    '\n  *[_type == "blogPage"][0]{\n    seo,\n    hero,\n    featuredArticle->{\n      _id,\n      title,\n      slug,\n      mainImage,\n      publishedAt,\n      "excerpt": body[0].children[0].text,\n      author->{name, image},\n      categories[]->{title}\n    },\n    cta\n  }\n': BlogPageQueryResult;
    '\n  *[_type == "page" && slug.current == $slug][0]{\n    _id,\n    title,\n    slug,\n    seo,\n    content\n  }\n': GenericPageQueryResult;
    '\n  {\n    "pages": *[_type == "page"]{ "slug": slug.current, _updatedAt },\n    "services": *[_type == "service"]{ "slug": slug.current, _updatedAt },\n    "conditions": *[_type == "condition"]{ "slug": slug.current, _updatedAt },\n    "posts": *[_type == "post"]{ "slug": slug.current, _updatedAt },\n    "successStories": *[_type == "successStory"]{ "slug": slug.current, _updatedAt }\n  }\n': SitemapQueryResult;
  }
}
